package com.example.creditcalculator;

import android.content.Context;
import android.graphics.Color;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;

import androidx.appcompat.app.AppCompatActivity;
import androidx.core.content.ContextCompat;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowCompat;
import androidx.core.view.WindowInsetsCompat;

import com.google.android.material.card.MaterialCardView;

public class InstructionActivity extends AppCompatActivity {
    @Override protected void attachBaseContext(Context c){super.attachBaseContext(AppPreferences.wrapLocale(c));}
    @Override protected void onCreate(Bundle b){AppPreferences.applyNightMode(this);super.onCreate(b);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);setContentView(build());}

    private View build(){
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);UiUtils.applyBackground(this,root);
        LinearLayout bar=new LinearLayout(this);bar.setOrientation(LinearLayout.HORIZONTAL);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setBackgroundColor(ContextCompat.getColor(this,R.color.primary));root.addView(bar,new LinearLayout.LayoutParams(-1,dp(56)));
        TextView back=top("‹",34);back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(dp(56),dp(56)));
        TextView title=top(local("Инструкция","User guide","Kullanım kılavuzu","Instrucciones"),20);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setGravity(Gravity.CENTER_VERTICAL);bar.addView(title,new LinearLayout.LayoutParams(0,-1,1f));
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1f));
        LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(20),dp(22),dp(20),dp(34));scroll.addView(content,new ScrollView.LayoutParams(-1,-2));
        content.addView(text(local("Как пользоваться приложением","How to use the app","Uygulama nasıl kullanılır","Cómo usar la aplicación"),27,R.color.text_main,true));
        TextView intro=text(local("Инструкция разделена по функциям. Нажмите на нужный блок, чтобы открыть его, и нажмите ещё раз, чтобы закрыть.","The guide is grouped by feature. Tap a block to open it and tap again to close it.","Kılavuz işlevlere göre gruplandırılmıştır. Açmak için bölüme, kapatmak için tekrar dokunun.","La guía está agrupada por funciones. Toca un bloque para abrirlo y vuelve a tocarlo para cerrarlo."),14,R.color.text_secondary,false);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,-2);ip.setMargins(0,dp(6),0,dp(18));content.addView(intro,ip);

        expandable(content,local("1. Начало работы и язык","1. Getting started and language","1. Başlangıç ve dil","1. Inicio e idioma"),local("При первом запуске выберите язык. После обычного входа приложение открывает «Мои платежи». Калькуляторы и остальные разделы доступны через боковое меню. Первый вход в «Мои платежи» и «Личный кабинет» сопровождается информационным окном с кнопкой «Понятно, продолжить». После подтверждения оно повторно не показывается, пока данные приложения не будут очищены.","Choose a language on first launch. Normal startup opens My payments. Calculators and other sections are available from the side menu. My payments and Personal cabinet show a one-time information notice on first entry.","İlk açılışta dili seçin. Normal başlangıç Ödemelerim bölümünü açar. Diğer bölümler yan menüdedir. Ödemelerim ve Kişisel alan ilk girişte bir bilgi penceresi gösterir.","Elige el idioma al iniciar por primera vez. El inicio normal abre Mis pagos. Las demás secciones están en el menú lateral. Mis pagos y Área personal muestran un aviso informativo la primera vez."));
        expandable(content,local("2. Калькуляторы","2. Calculators","2. Hesaplayıcılar","2. Calculadoras"),local("Доступны кредит, ипотека, автокредит, рассрочка и вклад. Заполните сумму, срок, ставку и остальные условия. Для кредита, ипотеки и автокредита можно выбрать аннуитетный или дифференцированный график. Денежные суммы форматируются пробелами. Расчёты ориентировочные: фактические банковские значения могут отличаться.","Loan, mortgage, auto loan, installment and deposit calculators are available. Enter amount, term, rate and other terms. Loan types can use annuity or differential schedules. Results are estimates and can differ from the bank.","Kredi, konut, araç kredisi, taksit ve mevduat hesaplayıcıları vardır. Sonuçlar yaklaşık değerlerdir ve bankadan farklı olabilir.","Hay calculadoras de préstamo, hipoteca, auto, cuotas y depósito. Los resultados son aproximados y pueden diferir del banco."));
        expandable(content,local("3. Мои платежи и общая сводка","3. My payments and summary","3. Ödemelerim ve özet","3. Mis pagos y resumen"),local("«Общая сводка» показывает только активные записи: общий остаток долга, сколько осталось оплатить в текущем месяце, сколько уже оплачено по графику, сколько обычных платежей осталось в месяце, ближайший платёж, следующий месяц, просрочки и проценты. Архивные кредиты сюда не входят. Потяните страницу вниз, чтобы перечитать локальные данные, пересчитать показатели и обновить напоминания. Кнопка сортировки показывает прямо на себе текущий режим, например «Ближайший платёж», «Дата: новые» или «Остаток долга ↓». В открытом списке активный вариант отмечен галочкой ✓. По умолчанию записи идут по ближайшему платежу.","Summary shows active items only: debt, current-month amount due, scheduled paid amount, remaining installment count, next payment, next month, overdue amounts and interest. Archived loans are excluded. Pull down to refresh. The sort button displays the current mode, for example Nearest payment, Date: newest or Debt ↓, and the active option is marked with ✓ in the popup. Nearest payment is the default.","Özet yalnızca aktif kayıtları gösterir. Arşiv kredileri dahil değildir. Yenilemek için aşağı çekin. Sıralama düğmesi geçerli sıralamayı gösterir ve açılan listede aktif seçenek ✓ ile işaretlenir. Varsayılan sıralama en yakın ödemedir.","El resumen solo incluye registros activos. Los créditos archivados no se incluyen. Desliza hacia abajo para actualizar. El botón de orden muestra el modo actual y la opción activa aparece con ✓ en la lista. Por defecto se usa el pago más cercano."));
        expandable(content,local("4. Ваша выгода, досрочное погашение и рефинансирование","4. Savings, early repayment and refinancing","4. Tasarruf, erken ödeme ve refinansman","4. Ahorro, amortización anticipada y refinanciación"),local("В карточке «Ваша выгода» показывается расчётная экономия только по активным кредитам. Там же показывается «Досрочно погашено по активным кредитам» — сумма всех зарегистрированных досрочных погашений за всё время по кредитам, которые сейчас активны. Это не показатель только текущего месяца. Как только кредит полностью закрывается и переходит в архив, его досрочные погашения и выгода перестают входить в активную карточку, но сохраняются в архиве и «Финансовой статистике». Досрочный платёж не смешивается с обычным ежемесячным платежом. При досрочном погашении можно уменьшить срок, уменьшить платёж или внести всю текущую сумму долга.","Your savings shows estimated savings for active loans only. It also shows lifetime early repayments for loans that are currently active. Once a loan is archived, its early repayments and savings leave the active card but remain in archive and Financial statistics. Early repayment is kept separate from normal installments.","Tasarruf kartı yalnızca aktif kredileri içerir. Aktif kredilerin tüm erken ödemeleri ayrıca gösterilir. Kredi arşive geçtiğinde bu veriler aktif karttan çıkar ancak arşivde ve Finansal istatistiklerde kalır.","La tarjeta Ahorro solo incluye créditos activos. También muestra todas las amortizaciones anticipadas de los créditos que siguen activos. Al archivar un crédito, esos datos salen de la tarjeta activa pero permanecen en el archivo y en Estadísticas financieras."));
        expandable(content,local("5. Финансовая статистика","5. Financial statistics","5. Finansal istatistikler","5. Estadísticas financieras"),local("Раздел «Финансовая статистика» находится в боковом меню и доступен также из «Личного кабинета». Он собирает активные и архивные данные, но не учитывает Корзину. Здесь показываются: сколько всего внесено по кредитам; сколько обычных платежей отмечено оплаченными; сколько внесено досрочно; сколько процентов уже выплачено; какая часть выплаченных процентов относится к архивным кредитам; сколько будущих процентов осталось по активным кредитам; текущий общий долг; выгода активных, архивных и всех кредитов; сумма активных вкладов; ожидаемый доход по активным вкладам; расчётный доход завершённых вкладов; количество активных и завершённых записей. У каждого показателя есть ⓘ с объяснением. Доход завершённых вкладов рассчитывается по сохранённым условиям и может отличаться от фактической суммы банка.","Financial statistics is available in the side menu and from Personal cabinet. It combines active and archived data, excluding Trash. It shows lifetime loan payments, early repayments, interest already paid, archived interest, future active interest, current debt, savings, active deposits, expected deposit income, estimated completed-deposit income and record counts. Every metric has an ⓘ explanation.","Finansal istatistikler yan menüde ve Kişisel alanda bulunur. Aktif ve arşiv verilerini birleştirir, Çöp kutusunu hariç tutar. Tüm göstergelerde ⓘ açıklaması vardır.","Estadísticas financieras está en el menú lateral y en Área personal. Combina datos activos y archivados, excluye Papelera y ofrece una explicación ⓘ para cada indicador."));
        expandable(content,local("6. Профиль и личный кабинет","6. Profile and personal cabinet","6. Profil ve kişisel alan","6. Perfil y área personal"),local("В верхней части бокового меню нажмите на блок профиля, чтобы указать имя и выбрать, сменить или убрать аватарку. Имя и выбранная аватарка хранятся только локально на телефоне и не требуют сервера или регистрации. Если отдельное имя профиля не задано, в боковом меню может использоваться ФИО из «Личного кабинета». В «Личном кабинете» можно сохранить ФИО, ежемесячный доход, другие обязательные платежи, известный рейтинг БКИ, количество заявок и отказов. Денежные поля форматируются, а долговая нагрузка и внутреннее «Кредитное здоровье» пересчитываются при вводе. «Кредитное здоровье» — внутренняя ориентировочная оценка приложения, а не официальный рейтинг БКИ.","Tap the profile block at the top of the side menu to set a name and choose, replace or remove an avatar. The profile name and avatar are stored locally on the device and require no server or registration. If no separate profile name is set, the full name from Personal cabinet may be used. Personal cabinet also stores income, other obligations, an optional bureau score, applications and rejections. Credit health is an internal estimate, not an official bureau score.","Yan menünün üstündeki profil bölümüne dokunarak adınızı ve avatarınızı ayarlayabilir, değiştirebilir veya kaldırabilirsiniz. Profil bilgileri yalnızca cihazda saklanır; sunucu veya kayıt gerekmez. Kişisel alanda gelir ve diğer finansal bilgiler de saklanabilir.","Toca el bloque de perfil en la parte superior del menú lateral para indicar un nombre y elegir, cambiar o quitar el avatar. El perfil se guarda solo en el dispositivo, sin servidor ni registro. El Área personal guarda además ingresos y otros datos financieros."));
        expandable(content,local("7. Архив и Корзина","7. Archive and Trash","7. Arşiv ve Çöp kutusu","7. Archivo y Papelera"),local("Полностью закрытый кредит переносится в архив и перестаёт участвовать в активной сводке и активной выгоде. Его история, досрочные погашения и выгода сохраняются для истории и статистики. Обычная оплата одного ежемесячного платежа не закрывает весь кредит. Корзина предназначена для удалённых записей и не участвует в «Финансовой статистике».","A fully closed loan moves to archive and is excluded from active summary and savings, while history remains available for statistics. Paying one installment does not archive the whole loan. Trash is excluded from Financial statistics.","Tam kapanan kredi arşive gider; geçmişi istatistiklerde kalır. Tek bir taksiti ödemek krediyi tamamen kapatmaz. Çöp kutusu istatistiklere dahil değildir.","Un crédito totalmente cerrado pasa al archivo; su historial permanece en las estadísticas. Pagar una cuota no archiva todo el crédito. Papelera no se incluye en las estadísticas."));
        expandable(content,local("8. Напоминания и отметка оплаты","8. Reminders and marking payments","8. Hatırlatmalar ve ödeme işareti","8. Recordatorios y marcar pagos"),local("В день платежа с 00:00 может показываться постоянное беззвучное уведомление, которое исчезает после отметки «Оплачено». В выбранное время отдельное звуковое напоминание срабатывает только для нерешённого платежа. Если платёж был отмечен ошибочно, его можно восстановить через архив платежей внутри графика записи. Досрочное погашение и обычный платёж учитываются отдельно.","On payment day a persistent silent notice can stay until the installment is marked paid. A separate sound reminder runs only for unresolved payments. An accidentally paid installment can be restored from the schedule's paid-payment archive. Early repayment and normal installments are tracked separately.","Ödeme gününde sessiz kalıcı bildirim ödeme işaretlenene kadar kalabilir. Erken ödeme ve normal taksitler ayrı izlenir.","El día de pago puede permanecer un aviso silencioso hasta marcar la cuota como pagada. La amortización anticipada y la cuota normal se registran por separado."));
        expandable(content,local("9. Безопасность","9. Security","9. Güvenlik","9. Seguridad"),local("Защиту можно настроить PIN-кодом, паролем, графическим ключом или системной защитой устройства. Биометрия используется только если она настроена в системе. Для отключения защиты требуется действующий способ разблокировки.","Protection can use a PIN, password, pattern or device credential. Biometrics work only when configured in the system. Disabling protection requires the current unlock method.","Koruma PIN, parola, desen veya cihaz kimlik bilgisi ile kullanılabilir. Biyometri sistemde yapılandırılmış olmalıdır.","La protección puede usar PIN, contraseña, patrón o credencial del dispositivo. La biometría debe estar configurada en el sistema."));
        expandable(content,local("10. Обратная связь и файлы","10. Feedback and files","10. Geri bildirim ve dosyalar","10. Comentarios y archivos"),local("В «О приложении» есть две отдельные кнопки: «Сообщить об ошибке» и «Предложить улучшение». Обе готовят письмо на SKRYTONsupport@gmail.com — пользователю не нужно вводить адрес получателя. Тема письма автоматически отличается для ошибки и предложения, а внизу письма добавляются название приложения, версия приложения, версия Android и модель устройства. Письмо отправляется через установленное на телефоне почтовое приложение пользователя, поэтому отдельный сервер не нужен. К обращению можно временно прикрепить до 5 фото или видео общим размером до 100 МБ. После отправки эти файлы приложение не хранит; в истории остаются только название, дата, тип и текст обращения. Также в «О приложении» есть кнопка «Оценить приложение».","About contains two separate buttons: Report a bug and Suggest an improvement. Both prepare an email to SKRYTONsupport@gmail.com, so the user does not enter the recipient. The subject differs by request type, and the app name, app version, Android version and device model are added automatically. The message is sent through the user's installed email app, so no separate server is required. Up to 5 photos or videos totaling 100 MB can be attached temporarily; attachments are not kept after sending, while request text remains in local history.","Hakkında bölümünde Hata bildir ve İyileştirme öner düğmeleri vardır. Her ikisi de alıcıyı otomatik olarak SKRYTONsupport@gmail.com yapar; uygulama ve cihaz bilgileri e-postaya eklenir. E-posta telefondaki posta uygulamasıyla gönderilir, ayrı sunucu gerekmez. Eklenen fotoğraf ve videolar gönderimden sonra saklanmaz.","En Acerca de hay dos botones: Informar de un error y Sugerir una mejora. Ambos preparan un correo para SKRYTONsupport@gmail.com sin pedir al usuario que escriba el destinatario. Se añaden automáticamente la aplicación, su versión, Android y el modelo del dispositivo. El correo se envía mediante la app de correo del usuario, sin servidor propio. Los archivos adjuntos no se guardan después del envío."));
        expandable(content,local("11. Реклама","11. Advertising","11. Reklam","11. Publicidad"),local("Для монетизации приложение может показывать адаптивный нижний рекламный баннер на внутренних экранах приложения. Экран «Настройки» намеренно остаётся без рекламы. Если реклама не загрузилась или интернет недоступен, рекламный блок скрывается и основные функции приложения продолжают работать.","For monetization, the app may show an adaptive bottom banner on its internal screens. The Settings screen intentionally remains ad-free. If an ad cannot load or the internet is unavailable, the ad area is hidden and the app's core functions continue to work.","Para kazanma amacıyla uygulamanın iç ekranlarında uyarlanabilir alt reklam bandı gösterilebilir. Ayarlar ekranı reklamsız kalır. Reklam yüklenemezse reklam alanı gizlenir ve temel işlevler çalışmaya devam eder.","Para monetización, la aplicación puede mostrar un banner adaptable en la parte inferior de sus pantallas internas. La pantalla Ajustes permanece sin publicidad. Si el anuncio no se carga, el espacio se oculta y las funciones principales siguen funcionando."));
        expandable(content,local("12. Важно о точности расчётов","12. Important calculation note","12. Hesaplama doğruluğu hakkında","12. Nota importante sobre los cálculos"),local("Все финансовые показатели приложения носят ориентировочный информационный характер. Фактические платежи, проценты, остаток долга, штрафы, комиссии, досрочное погашение, экономия и доход по вкладам могут отличаться от данных банка. Для точных значений используйте договор и информацию банка.","All financial figures are estimates for information. Actual payments, interest, balances, penalties, fees, early repayment, savings and deposit income may differ from bank data. Use your contract and bank information for exact values.","Tüm finansal değerler yaklaşık ve bilgilendirme amaçlıdır. Kesin değerler için banka sözleşmesini kullanın.","Todos los valores financieros son aproximados e informativos. Para cifras exactas, usa el contrato y los datos del banco."));

        ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars());v.setPadding(0,bars.top,0,0);scroll.setPadding(0,0,0,bars.bottom+dp(10));return insets;});
        return root;
    }

    private void expandable(LinearLayout parent,String title,String bodyText){
        MaterialCardView card=new MaterialCardView(this);card.setCardBackgroundColor(ContextCompat.getColor(this,R.color.card_background));card.setRadius(dp(16));card.setStrokeColor(ContextCompat.getColor(this,R.color.border));card.setStrokeWidth(dp(1));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,0,0,dp(10));parent.addView(card,cp);
        LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);card.addView(box);
        LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.HORIZONTAL);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(dp(16),dp(14),dp(12),dp(14));box.addView(head,new LinearLayout.LayoutParams(-1,-2));
        TextView h=text(title,16,R.color.text_main,true);head.addView(h,new LinearLayout.LayoutParams(0,-2,1f));TextView arrow=text("›",26,R.color.primary,true);arrow.setGravity(Gravity.CENTER);head.addView(arrow,new LinearLayout.LayoutParams(dp(36),dp(36)));
        TextView body=text(bodyText,14,R.color.text_secondary,false);body.setPadding(dp(16),0,dp(16),dp(16));body.setLineSpacing(0,1.15f);body.setVisibility(View.GONE);box.addView(body,new LinearLayout.LayoutParams(-1,-2));
        View.OnClickListener toggle=v->{boolean open=body.getVisibility()==View.VISIBLE;body.setVisibility(open?View.GONE:View.VISIBLE);arrow.setText(open?"›":"⌄");};head.setClickable(true);head.setOnClickListener(toggle);h.setOnClickListener(toggle);arrow.setOnClickListener(toggle);
    }

    private String local(String ru,String en,String tr,String es){String l=AppPreferences.getLanguage(this);if("tr".equals(l))return tr;if("es".equals(l))return es;if("en".equals(l))return en;return ru;}
    private TextView top(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);t.setClickable(true);return t;}
    private TextView text(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(ContextCompat.getColor(this,c));if(bold)t.setTypeface(null,android.graphics.Typeface.BOLD);return t;}
    private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
}